-- =============================================================================
-- website-services | Flyway V1 | 平台首批核心表（site / admin RBAC / site_user）
-- 数据库：PostgreSQL
-- 说明：不使用 UUID / 雪花 ID；主键使用 BIGINT GENERATED BY DEFAULT AS IDENTITY
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 通用：更新 updated_at（插入时使用 DEFAULT now()，后续变更由触发器刷新）
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_touch_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at := clock_timestamp();
    RETURN NEW;
END;
$$;

-- -----------------------------------------------------------------------------
-- site：站点主数据（多站点隔离根）
-- -----------------------------------------------------------------------------
CREATE TABLE site (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    site_code           VARCHAR(64) NOT NULL,
    site_name           VARCHAR(255) NOT NULL,
    site_type           VARCHAR(32) NOT NULL,
    status              VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
    default_domain      VARCHAR(255),
    description         TEXT,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by          BIGINT,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by          BIGINT,
    deleted             BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at          TIMESTAMPTZ,
    version             INTEGER NOT NULL DEFAULT 0
);

COMMENT ON TABLE site IS '前台站点主数据；car/cake 等行业通过 site_type 区分，不设 tenant_id';
COMMENT ON COLUMN site.site_code IS '站点编码，全平台唯一（软删除除外）';
COMMENT ON COLUMN site.site_type IS '站点类型：如 CAR、CAKE';
COMMENT ON COLUMN site.status IS '站点状态：ACTIVE、DISABLED 等';
COMMENT ON COLUMN site.default_domain IS '默认访问域名（首期单域名；多域名后续拆 site_domain）';

CREATE TRIGGER tr_site_touch_updated_at
    BEFORE UPDATE ON site
    FOR EACH ROW EXECUTE PROCEDURE fn_touch_updated_at();

CREATE UNIQUE INDEX uq_site_site_code_active ON site (site_code) WHERE deleted = FALSE;

CREATE INDEX idx_site_site_type_active ON site (site_type) WHERE deleted = FALSE;
CREATE INDEX idx_site_status_active ON site (status) WHERE deleted = FALSE;

-- -----------------------------------------------------------------------------
-- admin_user：后台管理员（与 site_user 隔离）
-- -----------------------------------------------------------------------------
CREATE TABLE admin_user (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username            VARCHAR(128) NOT NULL,
    email               VARCHAR(255),
    phone               VARCHAR(32),
    password_hash       VARCHAR(255),
    display_name        VARCHAR(255),
    status              VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
    last_login_at       TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by          BIGINT,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by          BIGINT,
    deleted             BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at          TIMESTAMPTZ,
    version             INTEGER NOT NULL DEFAULT 0
);

COMMENT ON TABLE admin_user IS '后台管理员账号；不属于任一 site';
COMMENT ON COLUMN admin_user.password_hash IS '密码哈希；明文不落库';

CREATE TRIGGER tr_admin_user_touch_updated_at
    BEFORE UPDATE ON admin_user
    FOR EACH ROW EXECUTE PROCEDURE fn_touch_updated_at();

CREATE UNIQUE INDEX uq_admin_user_username_active ON admin_user (username) WHERE deleted = FALSE;
CREATE UNIQUE INDEX uq_admin_user_email_active ON admin_user (lower(email)) WHERE deleted = FALSE AND email IS NOT NULL AND length(trim(email)) > 0;
CREATE UNIQUE INDEX uq_admin_user_phone_active ON admin_user (phone) WHERE deleted = FALSE AND phone IS NOT NULL AND length(trim(phone)) > 0;

CREATE INDEX idx_admin_user_status_active ON admin_user (status) WHERE deleted = FALSE;

-- -----------------------------------------------------------------------------
-- admin_role / admin_permission：RBAC 主体（首批仅结构，无种子数据）
-- -----------------------------------------------------------------------------
CREATE TABLE admin_role (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    role_code           VARCHAR(64) NOT NULL,
    role_name           VARCHAR(255) NOT NULL,
    description         TEXT,
    status              VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by          BIGINT,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by          BIGINT,
    deleted             BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at          TIMESTAMPTZ,
    version             INTEGER NOT NULL DEFAULT 0
);

COMMENT ON TABLE admin_role IS '后台角色';

CREATE TRIGGER tr_admin_role_touch_updated_at
    BEFORE UPDATE ON admin_role
    FOR EACH ROW EXECUTE PROCEDURE fn_touch_updated_at();

CREATE UNIQUE INDEX uq_admin_role_role_code_active ON admin_role (role_code) WHERE deleted = FALSE;
CREATE INDEX idx_admin_role_status_active ON admin_role (status) WHERE deleted = FALSE;

CREATE TABLE admin_permission (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    permission_code     VARCHAR(128) NOT NULL,
    permission_name     VARCHAR(255) NOT NULL,
    resource_type       VARCHAR(32),
    resource_key        VARCHAR(255),
    description         TEXT,
    status              VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by          BIGINT,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by          BIGINT,
    deleted             BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at          TIMESTAMPTZ,
    version             INTEGER NOT NULL DEFAULT 0
);

COMMENT ON TABLE admin_permission IS '后台权限点（菜单/API/ACTION 等由 resource_type + resource_key 表达）';

CREATE TRIGGER tr_admin_permission_touch_updated_at
    BEFORE UPDATE ON admin_permission
    FOR EACH ROW EXECUTE PROCEDURE fn_touch_updated_at();

CREATE UNIQUE INDEX uq_admin_permission_code_active ON admin_permission (permission_code) WHERE deleted = FALSE;
CREATE INDEX idx_admin_permission_status_active ON admin_permission (status) WHERE deleted = FALSE;

-- -----------------------------------------------------------------------------
-- admin_user_role / admin_role_permission：关联（软删除 + partial unique 防重复绑定）
-- -----------------------------------------------------------------------------
CREATE TABLE admin_user_role (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    admin_user_id       BIGINT NOT NULL,
    admin_role_id       BIGINT NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by          BIGINT,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by          BIGINT,
    deleted             BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at          TIMESTAMPTZ,
    version             INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT fk_admin_user_role_user FOREIGN KEY (admin_user_id) REFERENCES admin_user (id) ON DELETE RESTRICT,
    CONSTRAINT fk_admin_user_role_role FOREIGN KEY (admin_role_id) REFERENCES admin_role (id) ON DELETE RESTRICT
);

COMMENT ON TABLE admin_user_role IS '管理员与角色多对多';

CREATE TRIGGER tr_admin_user_role_touch_updated_at
    BEFORE UPDATE ON admin_user_role
    FOR EACH ROW EXECUTE PROCEDURE fn_touch_updated_at();

CREATE UNIQUE INDEX uq_admin_user_role_pair_active ON admin_user_role (admin_user_id, admin_role_id) WHERE deleted = FALSE;
CREATE INDEX idx_admin_user_role_user_id ON admin_user_role (admin_user_id) WHERE deleted = FALSE;
CREATE INDEX idx_admin_user_role_role_id ON admin_user_role (admin_role_id) WHERE deleted = FALSE;

CREATE TABLE admin_role_permission (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    admin_role_id       BIGINT NOT NULL,
    admin_permission_id BIGINT NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by          BIGINT,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by          BIGINT,
    deleted             BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at          TIMESTAMPTZ,
    version             INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT fk_admin_role_perm_role FOREIGN KEY (admin_role_id) REFERENCES admin_role (id) ON DELETE RESTRICT,
    CONSTRAINT fk_admin_role_perm_perm FOREIGN KEY (admin_permission_id) REFERENCES admin_permission (id) ON DELETE RESTRICT
);

COMMENT ON TABLE admin_role_permission IS '角色与权限多对多';

CREATE TRIGGER tr_admin_role_permission_touch_updated_at
    BEFORE UPDATE ON admin_role_permission
    FOR EACH ROW EXECUTE PROCEDURE fn_touch_updated_at();

CREATE UNIQUE INDEX uq_admin_role_perm_pair_active ON admin_role_permission (admin_role_id, admin_permission_id) WHERE deleted = FALSE;
CREATE INDEX idx_admin_role_perm_role_id ON admin_role_permission (admin_role_id) WHERE deleted = FALSE;
CREATE INDEX idx_admin_role_perm_perm_id ON admin_role_permission (admin_permission_id) WHERE deleted = FALSE;

-- -----------------------------------------------------------------------------
-- site_user：前台用户（按 site_id 隔离，car/cake 不拆表）
-- -----------------------------------------------------------------------------
CREATE TABLE site_user (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    site_id             BIGINT NOT NULL,
    username            VARCHAR(128),
    email               VARCHAR(255),
    phone               VARCHAR(32),
    password_hash       VARCHAR(255),
    status              VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
    last_login_at       TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by          BIGINT,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by          BIGINT,
    deleted             BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at          TIMESTAMPTZ,
    version             INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT fk_site_user_site FOREIGN KEY (site_id) REFERENCES site (id) ON DELETE RESTRICT
);

COMMENT ON TABLE site_user IS '前台站点统一用户；与 admin_user 隔离';
COMMENT ON COLUMN site_user.site_id IS '多站点隔离：统一使用 site_id，不使用 tenant_id';

CREATE TRIGGER tr_site_user_touch_updated_at
    BEFORE UPDATE ON site_user
    FOR EACH ROW EXECUTE PROCEDURE fn_touch_updated_at();

CREATE UNIQUE INDEX uq_site_user_site_username_active ON site_user (site_id, username) WHERE deleted = FALSE AND username IS NOT NULL AND length(trim(username)) > 0;
CREATE UNIQUE INDEX uq_site_user_site_email_active ON site_user (site_id, lower(email)) WHERE deleted = FALSE AND email IS NOT NULL AND length(trim(email)) > 0;
CREATE UNIQUE INDEX uq_site_user_site_phone_active ON site_user (site_id, phone) WHERE deleted = FALSE AND phone IS NOT NULL AND length(trim(phone)) > 0;

CREATE INDEX idx_site_user_site_id_active ON site_user (site_id) WHERE deleted = FALSE;
CREATE INDEX idx_site_user_status_active ON site_user (status) WHERE deleted = FALSE;

-- -----------------------------------------------------------------------------
-- site_user_profile：用户资料（与认证字段拆分；与 site_user 一对一）
-- -----------------------------------------------------------------------------
CREATE TABLE site_user_profile (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    site_id             BIGINT NOT NULL,
    site_user_id        BIGINT NOT NULL,
    display_name        VARCHAR(255),
    avatar_url          VARCHAR(1024),
    gender              VARCHAR(16),
    birthday            DATE,
    locale              VARCHAR(32),
    timezone            VARCHAR(64),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by          BIGINT,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by          BIGINT,
    deleted             BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at          TIMESTAMPTZ,
    version             INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT fk_site_user_profile_site FOREIGN KEY (site_id) REFERENCES site (id) ON DELETE RESTRICT,
    CONSTRAINT fk_site_user_profile_user FOREIGN KEY (site_user_id) REFERENCES site_user (id) ON DELETE RESTRICT
);

COMMENT ON TABLE site_user_profile IS '前台用户资料；首期不建 site_user_auth';

CREATE TRIGGER tr_site_user_profile_touch_updated_at
    BEFORE UPDATE ON site_user_profile
    FOR EACH ROW EXECUTE PROCEDURE fn_touch_updated_at();

CREATE UNIQUE INDEX uq_site_user_profile_user_active ON site_user_profile (site_user_id) WHERE deleted = FALSE;
CREATE INDEX idx_site_user_profile_site_id_active ON site_user_profile (site_id) WHERE deleted = FALSE;
